const body = $input.first().json.body || $input.first().json;

const toolCallList =
  body?.message?.toolCallList ||
  body?.message?.toolCalls ||
  body?.message?.tool_calls;

if (!Array.isArray(toolCallList) || toolCallList.length === 0) {
  const submission_id = body.submission_id || body.args?.submission_id;
  return [
    {
      json: {
        toolName: "check_patient",
        toolCallId: "test-call-001",
        args: { submission_id }
      }
    }
  ];
}

const first = toolCallList[0];

const toolName =
  first?.function?.name ||
  first?.name ||
  first?.function?.function?.name ||
  "check_patient";

const toolCallId = first?.id || first?.toolCallId || "missing-toolCallId";

const rawArgs =
  first?.function?.arguments ??
  first?.arguments ??
  first?.function?.function?.arguments;

const parsedArgs =
  typeof rawArgs === "string"
    ? JSON.parse(rawArgs || "{}")
    : (rawArgs || {});

const submission_id = parsedArgs.submission_id ?? body.submission_id ?? body.args?.submission_id;
const full_name = parsedArgs.full_name ?? body.full_name ?? body.args?.full_name;
const update_statement = parsedArgs.update_statement ?? body.update_statement ?? body.args?.update_statement;

return [
  {
    json: {
      toolName,
      toolCallId,
      args: {
        ...(submission_id ? { submission_id } : {}),
        ...(full_name ? { full_name } : {}),
        ...(update_statement ? { update_statement } : {})
      }
    }
  }
];

const allItems = $input.all();
const found = allItems.length > 0 && allItems[0].json && allItems[0].json.id !== undefined;
const toolCallId = $('Parse Tool Call').first().json.toolCallId;
const patientData = found ? allItems[0].json : null;

const result = found
  ? `true|${JSON.stringify(patientData)}`
  : 'false';

return [{
  json: {
    results: [
      {
        toolCallId: toolCallId,
        result: result
      }
    ]
  }
}];

const existing = $input.first().json;
const args = $('Parse Tool Call').first().json.args;
const updateStatement = args.update_statement;

return [{
  json: {
    existing_record: existing,
    update_statement: updateStatement,
    full_name: args.full_name,
    toolCallId: $('Parse Tool Call').first().json.toolCallId
  }
}];

const aiResponse = $input.first().json.message?.content || $input.first().json.text || $input.first().json.content;
const toolCallId = $('Prepare AI Context').first().json.toolCallId;
const fullName = $('Prepare AI Context').first().json.full_name;
const submissionId = $('Prepare AI Context').first().json.existing_record?.submission_key;
const existing = $('Fetch Existing Record').first().json;

let fullUpdated;
try {
  const clean = aiResponse.replace(/```json|```/g, '').trim();
  fullUpdated = JSON.parse(clean);
} catch(e) {
  throw new Error('AI returned invalid JSON: ' + aiResponse);
}

const arrayFields = [
  'conditions', 'surgeries', 'drug_allergies', 'food_allergies',
  'rx_meds', 'otc_meds', 'herbal_meds', 'immunisations',
  'mental_history', 'cognitive', 'directives', 'fam_history',
  'assistive', 'substance_use', 'pets_type', 'pregnancy_complications'
];

const notesFields = [
  'cond_other', 'surg_other', 'meds_notes', 'admit_details',
  'transfusion_details', 'imm_notes', 'mental_notes', 'mental_current',
  'dir_notes', 'fam_history_notes', 'assistive_notes',
  'substance_details', 'lifestyle_notes', 'obgyn_notes'
];

const changedFields = {};
for (const key of Object.keys(fullUpdated)) {
  const oldVal = existing[key];
  const newVal = fullUpdated[key];

  if (arrayFields.includes(key)) {
    const oldArr = Array.isArray(oldVal) ? oldVal : [];
    const newArr = Array.isArray(newVal) ? newVal : [];
    // Only keep truly new items
    const trulyNew = newArr.filter(item => !oldArr.includes(item));
    if (trulyNew.length > 0) {
      changedFields[key] = [...oldArr, ...trulyNew];
    }

  } else if (notesFields.includes(key)) {
    // Only append if new value is genuinely different and not already contained
    const oldStr = (oldVal || '').trim();
    const newStr = (newVal || '').trim();
    if (newStr && newStr !== oldStr && !oldStr.includes(newStr)) {
      changedFields[key] = `${oldStr}\n${newStr}`;
    }

  } else {
    // Replace single value fields only if changed
    if (JSON.stringify(oldVal) !== JSON.stringify(newVal)) {
      changedFields[key] = newVal;
    }
  }
}

return [{
  json: {
    changedFields,
    updatedFields: changedFields,
    fullName,
    submissionId,
    toolCallId
  }
}];

const toolCallId = $('Parse AI Response').first().json.toolCallId;
const updatedFields = $('Parse AI Response').first().json.updatedFields;
const fieldNames = Object.keys(updatedFields).join(', ');

return [{
  json: {
    results: [
      {
        toolCallId: toolCallId,
        result: `Your medical profile has been updated. Fields changed: ${fieldNames}. Is there anything else you would like to update?`
      }
    ]
  }
}];

const toolCallId = $('Parse Tool Call').first().json.toolCallId;

return [{
  json: {
    results: [
      {
        toolCallId: toolCallId,
        result: 'Patient Digital Medical Kit saved successfully.'
      }
    ]
  }
}];

