const { changedFields, submissionId, fullName, toolCallId, updatedFields } = $input.first().json;

// Spread only changedFields to top level for Supabase auto-mapping
// Prefix metadata fields with underscore so Supabase ignores them
return [{
  json: {
    ...changedFields,
    submission_key: submissionId,
    _fullName: fullName,
    _toolCallId: toolCallId,
    _updatedFields: updatedFields
  }
}];

const body = $input.first().json.body || $input.first().json;

function generateHex(length) {
  const chars = '0123456789abcdef';
  let hex = '';
  for (let i = 0; i < length; i++) {
    hex += chars[Math.floor(Math.random() * 16)];
  }
  return hex;
}

function generateSubmissionId() {
  return `EE_${generateHex(32)}`;
}

function generateUserId() {
  return `${generateHex(8)}-${generateHex(4)}-4${generateHex(3)}-${['8','9','a','b'][Math.floor(Math.random()*4)]}${generateHex(3)}-${generateHex(12)}`;
}

const submission_key = generateSubmissionId();
const user_id = generateUserId();

const args = {
  ...body.args,
  submission_key,
  user_id
};

const flatArgs = {};
for (const [key, val] of Object.entries(args)) {
  if (Array.isArray(val)) {
    flatArgs[key] = JSON.stringify(val);
  } else if (val === null || val === undefined) {
    flatArgs[key] = null;
  } else {
    flatArgs[key] = val;
  }
}

return [{ json: flatArgs }];

for (const key in $json) {
  if (typeof $json[key] === 'string') {
    $json[key] = $json[key].trim();
  }
}

return [{ json: $json }];
